package dev.algorithmlearning.api.dashboard.application; import static org.assertj.core.api.Assertions.assertThat; import java.util.*; import org.junit.jupiter.api.Test; class DashboardServiceDashboardTest { @Test void exposesZeroDifficultyCountsForAnEmptyLibrary(){var result=new DashboardService(new EmptyRepository()).dashboard(UUID.randomUUID());assertThat(result.totalProblems()).isZero();assertThat(result.easy()).isZero();} static class EmptyRepository implements DashboardRepository {public DashboardCounts counts(UUID owner){return new DashboardCounts(0,0,0,0,0);}}}
